-- RS3 Item Export (generated by the RS3 Plugin API extension for VS Code)
--
-- Sends the items in YOUR backpack, worn equipment and bank (name, config name, id) to VS Code,
-- so "RS3: Find Item…" can insert id.Obj.NAME for them. Only items you can already see; nothing else.
-- Open your bank once while this is enabled so the bank is included.
--
-- HTTP: grant it with   ppr rs3_item_export   ppe rs3_item_export httpAccess   then   prl rs3_item_export
-- Without HTTP it prints RS3X|… lines; copy them and run "RS3: Import Item Export Output" in VS Code.

local RUN = tostring(math.random(100000, 999999))
local INVS = { "INV", "WORN", "BANK" }
local seen, items, counts = {}, {}, {}

local function collect()
  local added = 0
  for _, name in ipairs(INVS) do
    pcall(function()
      local inv = Inventory.Find(config.Inv[name])
      if not inv then return end
      local slots = inv:GetSlots() or {}
      counts[name] = 0
      for _, slot in ipairs(slots) do
        local o = slot and slot.obj
        if o then
          counts[name] = counts[name] + 1
          local id = o.id
          if id and not seen[id] then
            seen[id] = true
            items[#items + 1] = { id = id, name = o.name, configName = o.configName, where = string.lower(name) }
            added = added + 1
          end
        end
      end
    end)
  end
  return added
end

local function enc(v)
  local t = type(v)
  if t == "nil" then return "null" end
  if t == "number" then return math.type(v) == "integer" and tostring(v) or string.format("%.6g", v) end
  if t == "boolean" then return v and "true" or "false" end
  if t == "string" then
    return '"' .. v:gsub('[%c"\\]', function(ch)
      local m = { ['"'] = '\\"', ['\\'] = '\\\\', ['\n'] = '\\n' }
      return m[ch] or string.format("\\u%04x", ch:byte())
    end) .. '"'
  end
  local parts = {}
  if #v > 0 then
    for i = 1, #v do parts[i] = enc(v[i]) end
    return "[" .. table.concat(parts, ",") .. "]"
  end
  for k, val in pairs(v) do parts[#parts + 1] = enc(tostring(k)) .. ":" .. enc(val) end
  return "{" .. table.concat(parts, ",") .. "}"
end

local outQueue = {}
local sends = 0
local function send()
  sends = sends + 1
  local json = enc({ source = "rs3-item-export", run = RUN, kind = "items", items = items, counts = counts })
  local canHttp = false
  pcall(function() canHttp = Plugin.urls.vscode ~= nil and Plugin.HasPermission(PluginPermissions.httpAccess) end)
  local function toConsole()
    local CHUNK, n = 800, math.ceil(#json / 800)
    for i = 1, n do outQueue[#outQueue + 1] = "RS3X|" .. RUN .. "|items" .. sends .. "|" .. i .. "/" .. n .. "|" .. json:sub((i - 1) * CHUNK + 1, i * CHUNK) end
    log("RS3 Item Export: printing " .. n .. " RS3X lines for VS Code.")
  end
  if canHttp then
    local ok = pcall(function()
      -- the client appends the path to the base URL as-is, so it needs the leading "/"
      local req = HTTPRequest.new(Plugin.urls.vscode, "/items")
      req:AddHeader("Content-Type", "application/json")
      req:Post(json, function(r)
        if r.successful then log(formatStr("RS3 Item Export: sent {} items to VS Code.", #items)) else toConsole() end
      end)
    end)
    if ok then return end
  end
  toConsole()
end

local pending = true
local function refresh()
  if collect() > 0 then pending = true end
end
refresh()

-- re-send when the bank (or backpack) changes, e.g. the first time you open the bank
pcall(function() Event.InventoryAdded.Subscribe("rs3itemexport", refresh) end)
pcall(function() Event.InventoryUpdated.Subscribe("rs3itemexport", refresh) end)

local tick = 0
Event.Logic.Subscribe("rs3itemexport", function()
  for _ = 1, 20 do
    if #outQueue == 0 then break end
    log(table.remove(outQueue, 1))
  end
  tick = tick + 1
  -- send at most every ~3 seconds (Logic runs 50 times a second)
  if pending and tick % 150 == 1 and #outQueue == 0 then
    pending = false
    send()
  end
end)

function PluginShutdown()
  pcall(function() Event.Logic.Unsubscribe("rs3itemexport") end)
  pcall(function() Event.InventoryAdded.Unsubscribe("rs3itemexport") end)
  pcall(function() Event.InventoryUpdated.Unsubscribe("rs3itemexport") end)
end
